    struct snd_card *card;
    int err;

    if (dev->quirks)
        snd_usb_apply_boot_quirk(dev, usb_id);

    if (snd_usb_get_status(dev) < 0)
        return -ENODEV;

    card = snd_card_new(index, id, this_module, sizeof(*card));
