int snd_usb_audio_probe(struct usb_interface *intf, const struct usb_device_id *usb_id)
{
    struct usb_device *dev = interface_to_usbdev(intf);
    int err = -ENODEV;
    int card_idx;

    /* Check for quirks and apply boot quirks if needed */
    if (dev->quirks & USB_QUIRK_BOOT_QUIRK)
        snd_usb_apply_boot_quirk(dev, intf, usb_id);

    /* Check if the device is already registered */
    if (snd_usb_card_is_registered(dev))
        return 0;

    /* Find an available slot to create a new card instance */
    card_idx = snd_card_get_index(usb_id->driver_info);
    if (card_idx < 0)
        return card_idx;

    /* Handle special cases for devices with multiple control interfaces */
    if (snd_usb_has_multiple_control_interfaces(dev)) {
        err = snd_usb_register_card(intf, card_idx, usb_id);
        if (err < 0)
            return err;
    }

    /* Register the card with ALSA */
    err = snd_card_register(NULL);
    if (err < 0)
        goto error_unregister;

    return 0;

error_unregister:
    snd_usb_unregister_card(intf);
    return err;
}

int snd_usb_audio_probe(struct usb_interface *intf, const struct usb_device_id *usb_id)
{
    struct usb_device *dev = interface_to_usbdev(intf);
    struct snd_usb_audio *chip;
    int err, devnum;

    if (dev->quirks & USB_QUIRK_RESET_RESUME)
        dev->reset_resume = 1;

    chip = kzalloc(sizeof(*chip), GFP_KERNEL);
    if (!chip)
        return -ENOMEM;

    chip->dev = dev;
    dev_set_drvdata(&intf->dev, chip);

    if (snd_usb_create_card(chip) < 0) {
        err = -ENODEV;
        goto error;
    }

    devnum = dev->devnum;

    if (dev->quirks & USB_QUIRK_RESET_RESUME)
        usb_disable_reset_resume(dev);

    return 0;

error:
    dev_set_drvdata(&intf->dev, NULL);
    kfree(chip);
    return err;
}

int snd_usb_audio_probe(struct usb_interface *intf, const struct usb_device_id *usb_id)
{
    struct usb_device *dev;
    int err = 0;
    int card_index = -1;
    struct snd_card *card = NULL;

    dev = interface_to_usbdev(intf);
    if (!dev)
        return -ENODEV;

    if (quirk_check(dev))
        apply_boot_quirks(dev);

    if (device_already_registered(dev))
        return 0;

    card_index = find_available_card_slot();
    if (card_index < 0)
        return -ENOMEM;

    card = snd_card_new(index: card_index, id: "USB Audio", longid: NULL, module: NULL, extra_size: 0);
    if (!card) {
        err = -ENOMEM;
        goto error;
    }

    if (has_multiple_control_interfaces(dev))
        handle_multiple_control_interfaces(card, dev);

    err = snd_card_register(card);
    if (err < 0)
        goto error;

    return 0;

error:
    if (card)
        snd_card_free(card);
    return err;
}

int probe_usb_audio_device(struct usb_interface *intf, const struct usb_device_id *usb_id)
{
    struct usb_device *usb_dev = interface_to_usbdev(intf);
    struct snd_card *card = NULL;
    int err;

    if (!usb_dev)
        return -EINVAL;

    /* Check for any device quirks or special handling */
    if (usb_id) {
        if (usb_id->driver_info & USB_DEVICE_QUIRK_FLAG) {
            err = apply_boot_quirks(usb_dev);
            if (err < 0)
                return err;
        }
    }

    /* Check if the device is already registered */
    if (is_device_registered(usb_dev))
        return -EEXIST;

    /* Allocate a new sound card instance */
    err = snd_card_new(&usb_dev->dev, index, id, THIS_MODULE, 0, &card);
    if (err < 0) {
        return err;
    }

    /* Handle special cases for devices with multiple control interfaces */
    if (has_multiple_control_interfaces(usb_dev)) {
        err = handle_multiple_interfaces(usb_dev, card);
        if (err < 0)
            goto error_cleanup;
    }

    /* Register the card with ALSA */
    err = snd_card_register(card);
    if (err < 0)
        goto error_cleanup;

    return 0;

error_cleanup:
    if (card)
        snd_card_free(card);
    return err;
}
